/**
 * HR authorization contract. These helpers may only narrow access.
 * All live HR endpoints must call them on the server after authentication,
 * tenant verification, explicit security permissions, and audit logging.
 */
export type HrAccessScope = 'self' | 'site' | 'manager_hierarchy';
export type HrDecision = { allowed: boolean; reason: string };
export type HrSubject = {
  tenantId: string; employeeUid: string; siteId: string;
  /** Verified ancestor manager UIDs generated by trusted HR organization mappings. */
  managerAncestorUids: string[];
};
export type HrActor = {
  tenantId: string; uid: string; siteIds: string[];
  permissions: string[];
};
export const HR_POLICY = Object.freeze({
  hrAccessScope: 'site' as const,
  managerAccessScope: 'manager_hierarchy' as const,
  approvalAssignment: 'independent' as const,
  requiresAudit: true,
  requiresIndependentCoA: true,
  defaultDeny: true,
});
const has = (a: HrActor, perm: string) => a.permissions.includes(perm);
/** Restrictive common-profile read, never authorizes financial or sensitive records. */
export function canReadHrBasicProfile(actor: HrActor, subject: HrSubject, scope: HrAccessScope): HrDecision {
  if (!actor.tenantId || !subject.tenantId || actor.tenantId !== subject.tenantId)
    return { allowed: false, reason: 'Different tenant or missing tenant' };
  if (scope === 'self')
    return actor.uid && actor.uid === subject.employeeUid
      ? { allowed: true, reason: 'Verified own record' } : { allowed: false, reason: 'Not own record' };
  if (scope === 'site')
    return has(actor, 'HRM.employee.site.read') && !!subject.siteId && actor.siteIds.includes(subject.siteId)
      ? { allowed: true, reason: 'Assigned HR site' } : { allowed: false, reason: 'Outside authorized HR site' };
  if (scope === 'manager_hierarchy')
    return has(actor, 'HRM.manager.hierarchy.read') && subject.managerAncestorUids.includes(actor.uid)
      ? { allowed: true, reason: 'Verified reporting hierarchy' } : { allowed: false, reason: 'Outside reporting hierarchy' };
  return { allowed: false, reason: 'Unknown access scope' };
}
/** Approval must come from a distinct approved security role plus current CoA binding. */
export function canApproveHrTransaction(input: {
  actorUid: string; requesterUid: string; assessorUid?: string;
  hasIndependentApproverRole: boolean; coaBound: boolean; workflowActive: boolean;
  permittedAmount: boolean; siteMatch: boolean;
}): HrDecision {
  if (!input.actorUid || input.actorUid === input.requesterUid || (input.assessorUid && input.actorUid === input.assessorUid))
    return { allowed: false, reason: 'Segregation of duties' };
  if (!input.hasIndependentApproverRole || !input.coaBound || !input.workflowActive || !input.permittedAmount || !input.siteMatch)
    return { allowed: false, reason: 'Missing security role, active approval, authority or site scope' };
  return { allowed: true, reason: 'Policy prerequisites met; transaction runtime must still verify and audit' };
}
